<div class="page-title"><div><em>OPERATIONS</em><h1><?=html_escape($heading)?></h1><p>Review and manage financial activity across the platform.</p></div><a class="outline" href="<?=site_url('admin/transactions/export'.($kind?'/'.$kind:''))?>">↓ Export report</a></div><section class="panel"><form class="filter" method="get"><input name="q" value="<?=html_escape($this->input->get('q',TRUE))?>" placeholder="⌕ Search reference, customer or category"><button class="outline">Search</button></form><div class="data-table admin-transactions"><div class="tr th"><span>Reference</span><span>Customer</span><span>Type</span><span>Amount</span><span>Date</span><span>Status / action</span></div><?php foreach($transactions as $t):?><div class="tr"><strong><?=$t['reference']?></strong><span><?=html_escape($t['first_name'].' '.$t['last_name'])?></span><span><?=html_escape($t['category'])?></span><strong class="<?=$t['type']?>"><?=money($t['amount'])?></strong><span><?=date('M j, Y',strtotime($t['transaction_date']))?></span><span><?php if($t['status']==='pending'):?><?=form_open('admin/transactions/'.$t['id'].'/status',array('class'=>'inline-form'))?><button name="status" value="completed" class="approve">Approve</button><button name="status" value="failed" class="decline">Decline</button></form><?php else:?><span class="<?=status_class($t['status'])?>"><?=ucfirst($t['status'])?></span><?php endif?></span></div><?php endforeach?></div></section>
